// Package tool holds the small set of capabilities compiled into erg:
// read, write, edit, glob, list, bash, ask, and task. Everything beyond this
// set is an external CLI driven through bash, per the project's extension
// philosophy. Each tool implements agent.Tool.
package tool

import (
	"bytes"
	"encoding/json"
	"fmt"
	"path/filepath"

	"github.com/emergingrobotics/erg/internal/agent"
)

const defaultMaxOutputBytes = 64 * 1024

// Core returns the default always-available toolset. sub may be nil to omit the
// task tool (e.g. inside a sub-run, to prevent unbounded recursion).
func Core(sub SubRunner) agent.Toolset {
	ts := agent.Toolset{
		readToolName:  Read{},
		writeToolName: Write{},
		editToolName:  Edit{},
		globToolName:  Glob{},
		listToolName:  List{},
		bashToolName:  Bash{},
		AskName:       Ask{},
	}
	if sub != nil {
		ts[taskToolName] = Task{Runner: sub}
	}
	return ts
}

// Select returns the subset of the core toolset named in enabled. An unknown
// name is a configuration error. An empty list yields the full core set.
func Select(all agent.Toolset, enabled []string) (agent.Toolset, error) {
	if len(enabled) == 0 {
		return all, nil
	}
	out := make(agent.Toolset, len(enabled))
	for _, name := range enabled {
		if name == SkillName {
			// The skill loader is managed by the wiring layer: it is injected
			// when a shape has lazy skills in an interactive loop, regardless of
			// this list. Listing it here is therefore harmless, not a Core pick.
			continue
		}
		tool, ok := all[name]
		if !ok {
			return nil, fmt.Errorf("unknown tool %q", name)
		}
		out[name] = tool
	}
	return out, nil
}

// decode unmarshals tool arguments, rejecting unknown fields so a malformed
// call fails loudly rather than being silently misinterpreted.
func decode(args json.RawMessage, dst any) error {
	dec := json.NewDecoder(bytes.NewReader(args))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return fmt.Errorf("invalid arguments: %w", err)
	}
	return nil
}

// resolvePath joins a possibly-relative path against the tool environment's
// working directory. Absolute paths are used as-is.
func resolvePath(env agent.ToolEnv, p string) string {
	if p == "" {
		return env.Cwd
	}
	if filepath.IsAbs(p) {
		return filepath.Clean(p)
	}
	return filepath.Join(env.Cwd, p)
}

// capBytes truncates s to n bytes, appending a truncation note when it cuts.
func capBytes(s string, n int) string {
	if n <= 0 || len(s) <= n {
		return s
	}
	return s[:n] + fmt.Sprintf("\n... [truncated %d bytes]", len(s)-n)
}

func ok(content string) (agent.ToolResult, error) {
	return agent.ToolResult{Content: content}, nil
}

func toolErr(content string) (agent.ToolResult, error) {
	return agent.ToolResult{Content: content, IsError: true}, nil
}

package tool

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/emergingrobotics/erg/internal/agent"
)

const (
	readToolName  = "read"
	writeToolName = "write"
	editToolName  = "edit"
	globToolName  = "glob"
	listToolName  = "list"
)

// Read returns the contents of a file, optionally a line range. A directory
// path yields a listing of its entries so the model can navigate the tree.
type Read struct{}

func (Read) Name() string { return readToolName }

func (Read) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        readToolName,
		Description: "Read a UTF-8 text file, or list a directory's entries when the path is a directory. Optionally start at a 1-based line offset and limit the number of lines (files only).",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "File path, absolute or relative to the working directory."},
    "offset": {"type": "integer", "description": "1-based first line to return."},
    "limit": {"type": "integer", "description": "Maximum number of lines to return."}
  },
  "required": ["path"]
}`),
	}
}

type readArgs struct {
	Path   string  `json:"path"`
	Offset flexInt `json:"offset"`
	Limit  flexInt `json:"limit"`
}

func (Read) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a readArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Path == "" {
		return toolErr("path is required")
	}
	path := resolvePath(env, a.Path)
	info, err := os.Stat(path)
	if err != nil {
		return toolErr(err.Error())
	}
	if info.IsDir() {
		listing, err := listDir(path)
		if err != nil {
			return toolErr(err.Error())
		}
		return ok(capBytes(listing, defaultMaxOutputBytes))
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return toolErr(err.Error())
	}
	content := string(data)
	if a.Offset > 0 || a.Limit > 0 {
		content = sliceLines(content, int(a.Offset), int(a.Limit))
	}
	return ok(capBytes(content, defaultMaxOutputBytes))
}

// listDir renders a directory's entries, one per line, sorted, with a trailing
// slash marking subdirectories so the model can tell files from directories.
func listDir(path string) (string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	fmt.Fprintf(&b, "directory %s (%d entries):\n", path, len(entries))
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			name += "/"
		}
		b.WriteString(name + "\n")
	}
	return b.String(), nil
}

func sliceLines(content string, offset, limit int) string {
	lines := strings.Split(content, "\n")
	start := 0
	if offset > 1 {
		start = offset - 1
	}
	if start > len(lines) {
		start = len(lines)
	}
	end := len(lines)
	if limit > 0 && start+limit < end {
		end = start + limit
	}
	return strings.Join(lines[start:end], "\n")
}

// Glob lists files matching a shell pattern, so the model can discover files by
// name without shelling out. Matches are returned relative to the working
// directory, sorted.
type Glob struct{}

func (Glob) Name() string { return globToolName }

func (Glob) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        globToolName,
		Description: "List files matching a glob pattern (e.g. \"src/*.c\", \"**/x*.go\"). Paths are relative to the working directory.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "pattern": {"type": "string", "description": "Glob pattern, absolute or relative to the working directory."}
  },
  "required": ["pattern"]
}`),
	}
}

type globArgs struct {
	Pattern string `json:"pattern"`
}

func (Glob) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a globArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Pattern == "" {
		return toolErr("pattern is required")
	}
	matches, err := filepath.Glob(resolvePath(env, a.Pattern))
	if err != nil {
		return toolErr(err.Error())
	}
	if len(matches) == 0 {
		return ok("no matches for " + a.Pattern)
	}
	sort.Strings(matches)
	for i, m := range matches {
		if rel, err := filepath.Rel(env.Cwd, m); err == nil && !strings.HasPrefix(rel, "..") {
			matches[i] = rel
		}
	}
	return ok(capBytes(strings.Join(matches, "\n"), defaultMaxOutputBytes))
}

// List returns a directory's entries. It is the same listing the read tool
// produces for a directory, offered under its own name so the model can list
// without shelling out.
type List struct{}

func (List) Name() string { return listToolName }

func (List) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        listToolName,
		Description: "List the entries of a directory. Subdirectories are marked with a trailing slash.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Directory path, absolute or relative to the working directory. Defaults to the working directory."}
  }
}`),
	}
}

type listArgs struct {
	Path string `json:"path"`
}

func (List) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a listArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	path := resolvePath(env, a.Path)
	info, err := os.Stat(path)
	if err != nil {
		return toolErr(err.Error())
	}
	if !info.IsDir() {
		return toolErr(path + " is not a directory")
	}
	listing, err := listDir(path)
	if err != nil {
		return toolErr(err.Error())
	}
	return ok(capBytes(listing, defaultMaxOutputBytes))
}

// Write creates or overwrites a file, creating parent directories as needed.
type Write struct{}

func (Write) Name() string { return writeToolName }

func (Write) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        writeToolName,
		Description: "Create or overwrite a file with the given content. Parent directories are created.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string"},
    "content": {"type": "string"}
  },
  "required": ["path", "content"]
}`),
	}
}

type writeArgs struct {
	Path    string `json:"path"`
	Content string `json:"content"`
}

func (Write) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a writeArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Path == "" {
		return toolErr("path is required")
	}
	path := resolvePath(env, a.Path)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return toolErr(err.Error())
	}
	if err := os.WriteFile(path, []byte(a.Content), 0o644); err != nil {
		return toolErr(err.Error())
	}
	return ok(fmt.Sprintf("wrote %d bytes to %s", len(a.Content), path))
}

// Edit performs an exact-match string replacement in a file. The match must be
// unique unless replace_all is set, so an ambiguous edit fails rather than
// changing the wrong occurrence.
type Edit struct{}

func (Edit) Name() string { return editToolName }

func (Edit) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        editToolName,
		Description: "Replace an exact substring in a file. old_string must occur exactly once unless replace_all is true.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string"},
    "old_string": {"type": "string"},
    "new_string": {"type": "string"},
    "replace_all": {"type": "boolean"}
  },
  "required": ["path", "old_string", "new_string"]
}`),
	}
}

type editArgs struct {
	Path       string `json:"path"`
	OldString  string `json:"old_string"`
	NewString  string `json:"new_string"`
	ReplaceAll bool   `json:"replace_all"`
}

func (Edit) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a editArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Path == "" || a.OldString == "" {
		return toolErr("path and old_string are required")
	}
	if a.OldString == a.NewString {
		return toolErr("old_string and new_string are identical")
	}
	path := resolvePath(env, a.Path)
	data, err := os.ReadFile(path)
	if err != nil {
		return toolErr(err.Error())
	}
	content := string(data)
	count := strings.Count(content, a.OldString)
	if count == 0 {
		return toolErr("old_string not found")
	}
	if count > 1 && !a.ReplaceAll {
		return toolErr(fmt.Sprintf("old_string occurs %d times; pass replace_all or make it unique", count))
	}
	var updated string
	replaced := 1
	if a.ReplaceAll {
		updated = strings.ReplaceAll(content, a.OldString, a.NewString)
		replaced = count
	} else {
		updated = strings.Replace(content, a.OldString, a.NewString, 1)
	}
	if err := os.WriteFile(path, []byte(updated), 0o644); err != nil {
		return toolErr(err.Error())
	}
	return ok(fmt.Sprintf("replaced %d occurrence(s) in %s", replaced, path))
}

// Package agent is the pure, provider-independent core of erg: the
// conversation item log, the turn state machine, and the continuation loop.
// It has no dependency on HTTP, terminals, sockets, or the wall clock except
// through interfaces its callers inject. Interfaces that the loop consumes
// (Provider, Tool) are declared here, at the consumer, so adapters depend on
// the core and never the reverse.
package agent

import (
	"context"
	"encoding/json"
	"time"
)

// StreamEventKind classifies a single event emitted by a provider stream.
type StreamEventKind int

const (
	EventTextDelta         StreamEventKind = iota // incremental assistant text
	EventToolCallStart                            // a tool call begins (Call has Index/ID/Name)
	EventToolCallArgsDelta                        // a fragment of a tool call's JSON arguments
	EventToolCallEnd                              // a tool call's arguments are complete
	EventUsage                                    // token accounting for the turn
	EventDone                                     // the provider finished this turn
	EventError                                    // the stream failed; Err is set
)

// ToolCallDelta carries the incremental pieces of a tool call as a provider
// streams it. Index identifies the call within one turn; ID and Name arrive
// with the start event, Args arrives in fragments.
type ToolCallDelta struct {
	Index int
	ID    string
	Name  string
	Args  string
}

// Usage is token accounting for one turn.
type Usage struct {
	InputTokens  int
	OutputTokens int
}

// Add accumulates usage across turns.
func (u *Usage) Add(o Usage) {
	u.InputTokens += o.InputTokens
	u.OutputTokens += o.OutputTokens
}

// StreamEvent is one provider-independent event. Adapters translate native
// wire events into these; the turn state machine folds them into items.
type StreamEvent struct {
	Kind  StreamEventKind
	Text  string
	Call  *ToolCallDelta
	Usage *Usage
	Err   error
}

// ToolCall is a completed request from the model to run a tool.
type ToolCall struct {
	ID   string
	Name string
	Args json.RawMessage
}

// ToolResult is the outcome of dispatching a ToolCall, fed back to the model.
type ToolResult struct {
	CallID  string
	Name    string
	Content string
	IsError bool
	// EndTurn asks the loop to stop the current user-turn after this result and
	// report the agent as blocked (needs a human decision). The `ask` tool sets
	// it; the loop stays generic and does not hardcode a tool name.
	EndTurn bool
}

// ToolSpec is the schema advertised to the model for one tool.
type ToolSpec struct {
	Name        string
	Description string
	Schema      json.RawMessage
}

// Request is the provider-independent model-visible context for one turn. It
// is built from the item log window; it is never assembled by slicing the raw
// log directly (see BuildRequest).
type Request struct {
	System string
	Items  []Item
	Tools  []ToolSpec
}

// Options selects model behavior for a turn.
type Options struct {
	Model  string
	Effort string
}

// ModelMeta is the resolved view of the active model, for display.
type ModelMeta struct {
	Name     string
	Provider string
}

// Provider is one model backend behind a native API family. Adapters own wire
// protocols and emit provider-independent StreamEvents; agent behavior must
// never branch on a native response shape.
type Provider interface {
	// Stream runs one turn, emitting events on the returned channel and
	// closing it when the turn ends. It must honor ctx cancellation.
	Stream(ctx context.Context, req Request, opts Options) (<-chan StreamEvent, error)
	// Model returns resolved capability metadata.
	Model() ModelMeta
}

// ToolEnv is the execution environment handed to a tool.
type ToolEnv struct {
	Cwd    string
	Limits ToolLimits
	// Unattended is true when no human is available to answer mid-run (one-shot,
	// observe reactions, sub-runs). Tools like ask use it to avoid dead-ends.
	Unattended bool
}

// ToolLimits bounds a single tool invocation.
type ToolLimits struct {
	Timeout time.Duration
}

// Tool is a single capability the model can invoke.
type Tool interface {
	Name() string
	Spec() ToolSpec
	Run(ctx context.Context, args json.RawMessage, env ToolEnv) (ToolResult, error)
}

// Toolset is the set of enabled tools, keyed by name.
type Toolset map[string]Tool

// Specs returns the advertised schema for every tool in the set.
func (t Toolset) Specs() []ToolSpec {
	specs := make([]ToolSpec, 0, len(t))
	for _, tool := range t {
		specs = append(specs, tool.Spec())
	}
	return specs
}

// AgentStatus is the semantic state erg reports to its runtime (see herdr).
type AgentStatus int

const (
	StatusIdle    AgentStatus = iota // awaiting input; observe watching
	StatusWorking                    // running a turn or a triggered reaction
	StatusBlocked                    // needs a human decision (ask tool, or hit max_turns)
	StatusDone                       // one-shot finished; observe watch terminated
)

func (s AgentStatus) String() string {
	switch s {
	case StatusIdle:
		return "idle"
	case StatusWorking:
		return "working"
	case StatusBlocked:
		return "blocked"
	case StatusDone:
		return "done"
	default:
		return "unknown"
	}
}

