// resolvePath joins a possibly-relative path against the tool environment's
// working directory and validates it stays within the workspace (sandbox).
// Absolute paths are resolved relative to the working directory to prevent
// escaping the sandbox. Returns an error if the path would escape.
func resolvePath(env agent.ToolEnv, p string) (string, error) {
	if p == "" {
		return env.Cwd, nil
	}
	// Join the path with the working directory
	resolved := filepath.Join(env.Cwd, p)
	// Clean to resolve . and .. components
	resolved = filepath.Clean(resolved)
	// Ensure the resolved path is within the workspace
	if !isSubPath(env.Cwd, resolved) {
		return "", fmt.Errorf("path traversal blocked: %s escapes workspace", p)
	}
	return resolved, nil
}

// isSubPath reports whether child is a sub-path of parent (or equal to it).
// Both paths must be clean absolute paths.
func isSubPath(parent, child string) bool {
	if parent == child {
		return true
	}
	// Ensure parent ends with a separator so we match exact directory boundaries
	if !strings.HasSuffix(parent, string(filepath.Separator)) {
		parent = parent + string(filepath.Separator)
	}
	return strings.HasPrefix(child, parent)
}

