// Package tool holds the small set of capabilities compiled into erg:
// read, write, edit, glob, list, bash, ask, and task. Everything beyond this
// set is an external CLI driven through bash, per the project's extension
// philosophy. Each tool implements agent.Tool.
package tool

import (
	"bytes"
	"encoding/json"
	"fmt"
	"path/filepath"

	"github.com/emergingrobotics/erg/internal/agent"
)

const defaultMaxOutputBytes = 64 * 1024

// Core returns the default always-available toolset. sub may be nil to omit the
// task tool (e.g. inside a sub-run, to prevent unbounded recursion).
func Core(sub SubRunner) agent.Toolset {

package tool

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/emergingrobotics/erg/internal/agent"
)

func env(t *testing.T) agent.ToolEnv {
	t.Helper()
	return agent.ToolEnv{Cwd: t.TempDir()}
}

func run(t *testing.T, tool agent.Tool, e agent.ToolEnv, args string) agent.ToolResult {
	t.Helper()
	res, err := tool.Run(context.Background(), json.RawMessage(args), e)
	if err != nil {
		t.Fatalf("%s run error: %v", tool.Name(), err)
	}
	return res
}

func TestWriteThenRead(t *testing.T) {
	e := env(t)
	res := run(t, Write{}, e, `{"path":"sub/hello.txt","content":"hi there"}`)
	if res.IsError {
		t.Fatalf("write failed: %s", res.Content)
	}
	res = run(t, Read{}, e, `{"path":"sub/hello.txt"}`)
	if res.IsError || res.Content != "hi there" {
		t.Fatalf("read got %+v", res)
	}
}

func TestReadMissingFile(t *testing.T) {
	res := run(t, Read{}, env(t), `{"path":"nope.txt"}`)
	if !res.IsError {
		t.Fatal("expected error reading missing file")
	}
}

func TestReadListsDirectory(t *testing.T) {
	e := env(t)
	os.WriteFile(filepath.Join(e.Cwd, "a.txt"), []byte("x"), 0o644)
	os.MkdirAll(filepath.Join(e.Cwd, "sub"), 0o755)

	res := run(t, Read{}, e, `{"path":"."}`)
	if res.IsError {
		t.Fatalf("directory read failed: %s", res.Content)
	}
	if !strings.Contains(res.Content, "a.txt") {
		t.Fatalf("listing missing file entry: %q", res.Content)
	}
	if !strings.Contains(res.Content, "sub/") {
		t.Fatalf("listing should mark subdirectories with a trailing slash: %q", res.Content)
	}
}

func TestReadLineRange(t *testing.T) {
	e := env(t)
	os.WriteFile(filepath.Join(e.Cwd, "f.txt"), []byte("a\nb\nc\nd\ne"), 0o644)
	res := run(t, Read{}, e, `{"path":"f.txt","offset":2,"limit":2}`)
	if res.Content != "b\nc" {
		t.Fatalf("expected b,c got %q", res.Content)
	}
}

// Small local models often stringify or float integer args. These forms must
// coerce; a non-numeric value must still fail.
func TestReadCoercesNumericArgs(t *testing.T) {
	e := env(t)
	os.WriteFile(filepath.Join(e.Cwd, "f.txt"), []byte("a\nb\nc\nd\ne"), 0o644)
	for _, limit := range []string{`2`, `"2"`, `"2.0"`, `2.0`} {
		res := run(t, Read{}, e, `{"path":"f.txt","offset":1,"limit":`+limit+`}`)
		if res.IsError || res.Content != "a\nb" {
			t.Fatalf("limit=%s: expected a,b got %+v", limit, res)
		}
	}
}

func TestReadRejectsNonNumericLimit(t *testing.T) {
	res, err := Read{}.Run(context.Background(), json.RawMessage(`{"path":"x","limit":"abc"}`), env(t))
	if err == nil {
		t.Fatalf("expected error for non-numeric limit, got %+v", res)
	}
}

func TestBashCoercesStringTimeout(t *testing.T) {
	res := run(t, Bash{}, env(t), `{"command":"sleep 5","timeout_seconds":"1"}`)
	if !res.IsError || !strings.Contains(res.Content, "timed out") {
		t.Fatalf("expected timeout with stringified seconds, got %+v", res)
	}
}

func TestEditUniqueAndAmbiguous(t *testing.T) {
	e := env(t)
	os.WriteFile(filepath.Join(e.Cwd, "f.txt"), []byte("foo bar foo"), 0o644)

	// Ambiguous without replace_all.
	res := run(t, Edit{}, e, `{"path":"f.txt","old_string":"foo","new_string":"X"}`)
	if !res.IsError {
		t.Fatal("expected ambiguity error")
	}

	// replace_all succeeds.
	res = run(t, Edit{}, e, `{"path":"f.txt","old_string":"foo","new_string":"X","replace_all":true}`)
	if res.IsError {
		t.Fatalf("replace_all failed: %s", res.Content)
	}
	data, _ := os.ReadFile(filepath.Join(e.Cwd, "f.txt"))
	if string(data) != "X bar X" {
		t.Fatalf("got %q", data)
	}
}

func TestEditNotFound(t *testing.T) {
	e := env(t)
	os.WriteFile(filepath.Join(e.Cwd, "f.txt"), []byte("abc"), 0o644)
	res := run(t, Edit{}, e, `{"path":"f.txt","old_string":"zzz","new_string":"q"}`)
	if !res.IsError {
		t.Fatal("expected not-found error")
	}
}

func TestBashOutputAndExit(t *testing.T) {
	e := env(t)
	res := run(t, Bash{}, e, `{"command":"echo hello"}`)
	if res.IsError || strings.TrimSpace(res.Content) != "hello" {
		t.Fatalf("bash echo got %+v", res)
	}
	res = run(t, Bash{}, e, `{"command":"exit 3"}`)
	if !res.IsError || !strings.Contains(res.Content, "exit status 3") {
		t.Fatalf("expected exit status 3, got %+v", res)
	}
}

func TestBashTimeout(t *testing.T) {
	res := run(t, Bash{}, env(t), `{"command":"sleep 5","timeout_seconds":1}`)
	if !res.IsError || !strings.Contains(res.Content, "timed out") {
		t.Fatalf("expected timeout, got %+v", res)
	}
}

func TestBashRunsInCwd(t *testing.T) {
	e := env(t)
	os.WriteFile(filepath.Join(e.Cwd, "marker"), []byte("x"), 0o644)
	res := run(t, Bash{}, e, `{"command":"ls"}`)
	if !strings.Contains(res.Content, "marker") {
		t.Fatalf("expected to see marker file, got %q", res.Content)
	}
}

func TestDecodeRejectsUnknownFields(t *testing.T) {
	res, err := Read{}.Run(context.Background(), json.RawMessage(`{"path":"x","bogus":1}`), env(t))
	if err == nil {
		t.Fatalf("expected decode error, got result %+v", res)
	}
}

func TestAskEndsTurnAndBlocks(t *testing.T) {
	res := run(t, Ask{}, env(t), `{"question":"proceed with the deploy?"}`)
	if res.IsError {
		t.Fatalf("unexpected error: %s", res.Content)
	}
	if !res.EndTurn {
		t.Fatal("ask must end the turn (EndTurn) so the agent reports blocked")
	}
	if miss := run(t, Ask{}, env(t), `{}`); !miss.IsError {
		t.Fatal("expected error for a missing question")
	}
}

func TestAskIsACoreTool(t *testing.T) {
	if _, ok := Core(nil)["ask"]; !ok {
		t.Fatal("ask should be a core tool")
	}
}

func TestAskUnattendedDoesNotBlock(t *testing.T) {
	res, err := Ask{}.Run(context.Background(), json.RawMessage(`{"question":"ok?"}`),
		agent.ToolEnv{Unattended: true})
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if res.EndTurn {
		t.Fatal("unattended ask must not end the turn (no human can answer)")
	}
	if res.IsError {
		t.Fatalf("unexpected error: %s", res.Content)
	}
}

func TestSelect(t *testing.T) {
	all := Core(nil)
	got, err := Select(all, []string{"read", "bash"})
	if err != nil {
		t.Fatalf("select: %v", err)
	}
	if len(got) != 2 || got["read"] == nil || got["bash"] == nil {
		t.Fatalf("bad selection: %v", got)
	}
	if _, err := Select(all, []string{"nope"}); err == nil {
		t.Fatal("expected error for unknown tool")
	}
}

func TestSelectIgnoresManagedSkillTool(t *testing.T) {
	// The skill loader is injected by the wiring layer, not selected from Core,
	// so listing it must not error and must not appear in the Core selection.
	got, err := Select(Core(nil), []string{"read", SkillName})
	if err != nil {
		t.Fatalf("select with skill listed should not error: %v", err)
	}
	if _, ok := got[SkillName]; ok {
		t.Fatal("skill should not be pulled from Core by Select")
	}
	if _, ok := got["read"]; !ok {
		t.Fatal("read should still be selected")
	}
}

func TestTaskRequiresRunner(t *testing.T) {
	res, _ := Task{}.Run(context.Background(), json.RawMessage(`{"shape":"s","prompt":"p"}`), agent.ToolEnv{})
	if !res.IsError {
		t.Fatal("expected error when runner is nil")
	}
	called := false
	tk := Task{Runner: func(_ context.Context, shape, prompt string) (string, error) {
		called = true
		return "sub-answer", nil
	}}
	res, _ = tk.Run(context.Background(), json.RawMessage(`{"shape":"s","prompt":"p"}`), agent.ToolEnv{})
	if !called || res.Content != "sub-answer" {
		t.Fatalf("task runner not invoked correctly: %+v", res)
	}
}

func TestSkillToolLoadsKnownAndErrorsUnknown(t *testing.T) {
