func TestGlobMatchesRelativeToCwd(t *testing.T) {
	e := env(t)
	os.MkdirAll(filepath.Join(e.Cwd, "src"), 0o755)
	os.WriteFile(filepath.Join(e.Cwd, "src", "a.c"), []byte("x"), 0o644)
	os.WriteFile(filepath.Join(e.Cwd, "src", "b.c"), []byte("x"), 0o644)
	os.WriteFile(filepath.Join(e.Cwd, "src", "notes.txt"), []byte("x"), 0o644)

	res := run(t, Glob{}, e, `{"pattern":"src/*.c"}`)
	if res.IsError {
		t.Fatalf("glob failed: %s", res.Content)
	}
	if res.Content != "src/a.c\nsrc/b.c" {
		t.Fatalf("expected sorted relative matches, got %q", res.Content)
	}

	res = run(t, Glob{}, e, `{"pattern":"src/*.go"}`)
	if res.IsError || !strings.Contains(res.Content, "no matches") {
		t.Fatalf("expected no-match message, got %+v", res)
	}
}

func TestListDirectory(t *testing.T) {
	e := env(t)
	os.WriteFile(filepath.Join(e.Cwd, "a.txt"), []byte("x"), 0o644)
	os.MkdirAll(filepath.Join(e.Cwd, "sub"), 0o755)

	res := run(t, List{}, e, `{"path":"."}`)
	if res.IsError {
		t.Fatalf("list failed: %s", res.Content)
	}
	if !strings.Contains(res.Content, "a.txt") || !strings.Contains(res.Content, "sub/") {
		t.Fatalf("listing wrong: %q", res.Content)
	}

	// A file path is not a directory.
	res = run(t, List{}, e, `{"path":"a.txt"}`)
	if !res.IsError {
		t.Fatal("listing a file should error")
	}
}

